import { HistoricalDocument } from '../../types';

export const ordenacoesLivro1TitulosLiALx: HistoricalDocument = {
  id: 'ordenacoes-livro-1-titulos-li-a-lx',
  title: 'Ordenações Filipinas — Títulos LI a LX',
  subtitle: 'Do Juiz da India, Mina e Guiné',
  date: '1603',
  era: 'Idade Moderna',
  language: 'Português',
  description: `Títulos LI a LX do Livro Primeiro das Ordenações Filipinas: de "Do Juiz da India, Mina e Guiné" a "Como os Corregedores das Comarcas, Ouvidores dos Mestrados, e de Senhores de terras, e Juizes de fóra darão residencia".`,
  parentCollectionId: 'ordenacoes-livro-1',
  sections: [
    {
      id: 'titulo-li',
      title: `LI. Do Juiz da India, Mina e Guiné`,
      type: 'articles',
      articles: [
        { id: 'of1-tli-preambulo', number: 'Preâmbulo', text: `Ao Juiz da India, Mina e Guiné pertence examinar e justificar as procurações e scripturas, per que nas Casas da India, Mina e Armazens se houverem de recadar, ou pagar quaesquer direitos. E bem assi conhecer dos furtos e delictos commettidos nas ditas Casas e Armazens, e nas carregas e descarregas, que a ellas pertencerem, das Nãos e Navios, que forem para féra, e vierem de quaesquer partes: dos quaes casos nenhum outro Julgador tomará conhecimento.` },
        { id: 'of1-tli-1', number: '1', text: `E fará o dito Juiz as justificações das Casas da India, Mina, Guiné, Brasil, Armazens e viagens, e as despachará per si só. E querendo as partes aggravar, o poderão fazer para os Desembargadores dos Aggravos da Casa da Supplicação, postoque as causas sejam de Captivos.` },
        { id: 'of1-tli-2', number: '2', text: `Item, tomará conhecimento das causas, que algumas pessoas tiverem com outras per razão de pedraria e outras encommendas, que lhes trouxessem da India, ou de outras partes de fóra destes Reinos. E havemos por bem, que as ditas pessoas possam demandar as ditas encommendas, sem por isso incorrerem em pena alguma, postoque a tal pedraria e cousas outras viessem mellidas em cartas, ou em lugares alguns, per que pareça, que as querião salvar sem pagar direitos. E posto que a quantia passe de sessenta mil réis, a poderão provar pela prova, que o Direito commum requere, sem embargo da Ordenação do Livro Terceiro, Titulo 59: Das provas que se devem fazer per scripturas publicas. E daquillo, que per sentença ás taes pessoas se mandar pagar, pagarão os direitos ordenados na Casa da India.` },
        { id: 'of1-tli-3', number: '3', text: `Item, conhecerá das demandas, que se moverem sobre frétes, os quaes mandará depositar na fórma, em que o ha de fazer o Ouvidor da Alfandega, confórme a seu Regimento. E bem assi conhecerá de avarias, custos de Nãos e Navios, ou outras cousas de Guiné, Arguim, India, Brasil, Çofalla, ou dos lugares, que se regulam pelas leis de Guiné e India; e assi conhecerá dos tratos, convenças e maleficios, que nos ditos lugares e navegação delles, ou sobre cousas delles, ou para elles se fazem, de que nenhum outro Julgador conhecerá, postoque as partes se desafórem.` },
        { id: 'of1-tli-4', number: '4', text: `Item, tirará as devassas ordinarias nos Navios da Mina e Brasil, Nãos da India, e lugares acima ditos, e as pronunciará per si só, e mandará prender os culpados, e aggravando-se delle alguma parte, o poderá fazer per petição à Relação.` },
        { id: 'of1-tli-5', number: '5', text: `E achando nas ditas devassas, ou em quaesquer outras, que per Nós lhe forem mandadas tirar, ou lhe vierem per qualquer outra via ter á mão, culpados alguns Officiaes das Casas da India, Mina e Armazens, Capitães, Scrivães, Mestres, Pilotos das Nãos da India, Mina, Guiné, Brasil, e mais lugares acima ditos e Capitães de Fortalezas, Alcaides Móres, Juizes das Alfandegas, Feitores, Almoxarifes, Recebedores e Scrivães dos ditos cargos das ditas partes, remeterá as ditas devassas, autos e papeis ao Juiz da Fazenda da Casa da Supplicação, o qual as despachará conforme a seu Regimento. Porém nos feitos de todas as outras pessoas, que não forem as acima nomeadas, assi civeis como crimes, e descaminhados, que se tomarem, conhecerá o Juiz da India e Mina.` },
        { id: 'of1-tli-6', number: '6', text: `E despachará per si só todos os feitos crimes e civeis, e os sentenciará em final. E das sentenças finaes, que der nos feitos civeis, dará aggravo para os Desembardores dos Aggravos da Casa da Supplicação, de que se pagará novecentos réis na Chancellaria. E das sentenças finaes, que der nos feitos crimes, se appellará para os Ouvidores da dita Casa, ou para os Juizes, a que o conhecimento per nossas Ordenações pertencer. E das interlocutorias, assi nos feitos crimes como civeis, nos casos em que per nossas Ordenações se pôde aggravar, o poderão as partes fazer per petição à Relação.` },
        { id: 'of1-tli-7', number: '7', text: `E terá a alçada, que temos dada aos Corregedores das Comarcas, como em Regimento se contém.` },
      ],
    },
    {
      id: 'titulo-lii',
      title: `LII. Do Ouvidor da Alfandega da cidade de Lisboa`,
      type: 'articles',
      articles: [
        { id: 'of1-tlii-preambulo', number: 'Preâmbulo', text: `O Ouvidor da Alfandega conhecerá dos feitos civeis, que perante elle se moverem entre quaesquer Mercadores, ou Tratantes, assi naturaes, como Estrangeiros, sobre quaesquer tratos e mercadorias, pagamentos, ou entrega dellas. E sobre dúvidas e cousas, que dos ditos tratos e mercadorias dependerem, quando os autores perante elle quizerem demandar, se não tiverem já citados os réos perante outros Julgadores, ou á outros Juizos não pertencerem particularmente, porque então poderão declinar o dito Juizo a seu tempo, sendo os que se demandam achados na dita cidade e seu termo.` },
        { id: 'of1-tlii-1', number: '1', text: `Item, conhecerá de quaesquer frétes, avarias, custas e soldos, que perante elle forem demandados, não sendo de Nãos, ou Navios dos lugares, de que o conhe- cimento pertence ao Juiz da India e Mina, como em seu Titulo 51 se contém.` },
        { id: 'of1-tlii-2', number: '2', text: `E conhecerá dos feitos civeis dos Mercadores Gallegos, e outros quaesquer, que á dita cidade trouxerem madeira, taboado, bordos, fruta, e outras mercadorias: E dos stantes na dita cidade, a que as ditas cousas entregarem para lhes feitorizarem, ácerca do que tocar ás mercadorias, frétes e pagamentos dellas.` },
        { id: 'of1-tlii-3', number: '3', text: `Item, conhecerá dos feitos dos Mercadores, que per mar trouxerem á dita cidade mercadorias, ou mantimentos, querendo elles demandar alguns moradores della, ou seu termo, ou stantes, por quaesquer cousas, postoque não seja sobre suas mercadorias, nem cousas que dellas dependam: não tendo as taes pessoas outro Juiz por special privilegio, porque essas poderão declinar o Juizo da Alfandega a seu tempo.` },
        { id: 'of1-tlii-4', number: '4', text: `Item, poderá conhecer dos feitos civeis dos Mareantes, moradores na dita cidade e seu termo, que navegam de foz em fóra: e dos Mareantes Estrangeiros e naturaes, que em quaesquer Nãos, ou Návios á dita cidade vierem, sobre suas mercadorias e cousas, que carregarem, e no que tocar ao repairo e corregimento dos ditos Návios, e de outras quaesquer cousas, que as suas navegações, frétes e soldos pertencem: E dos feitos que elles entre si, ou elles contra outros, ou outros contra elles tiverem.` },
        { id: 'of1-tlii-5', number: '5', text: `E bem assi poderá conhecer de feitos civeis de barqueiros, ou seus companheiros, que entre si, ou contra outros tiverem, assi os naturaes da cidade e seu termo, como de fóra. E ácerca do que tocar aos frétes, pagamentos, partilhas, corregimentos, apparelhos, partidas, stadas, carregas e descarregas das ditas barcas, por o dito Juizo star em lugar, onde podem requerer sua justiça mais facilmente.` },
        { id: 'of1-tlii-6', number: '6', text: `Poderá outrosi conhecer de quaesquer scripturas desaforadas, per que forem quaesquer pessoas no dito Juizo demandadas, sendo os demandados moradores, ou stantes na dita cidade e seu termo, ou nella achados, postoque não seja sobre tratos e mercadorias, com tanto que não seja sobre cousa, de que o conhecimento pertence ao Juiz da India.` },
        { id: 'of1-tlii-7', number: '7', text: `Item, fará contar com muita diligencia os feitos pelo Contador do dito Juizo, salvo sendo elle negligente, porque então os mandará contar a outro, que haverá seu salario inteiro.` },
        { id: 'of1-tlii-8', number: '8', text: `Outrosi poderá conhecer dos feitos de pessoas, que nos deverem alguma cousa na Alfandega de compras, ou direitos, ou postoque sejam pessoas Ecclesiasticas, ou Religiosas, porque para recadação dos nossos Direitos bem podem ser demandados perante nossas Justiças, segundo per capitulo de Cortes foi acordado entre os Reis passados e a Cleresia; do que não tomará conhecimento, senão quando o Thesoureiro da Alfandega, a que a execução pertencer, ou o Juiz da dizima da dita Alfandega, ou os Rendeiros della, perante elle quizerem demandar.` },
        { id: 'of1-tlii-9', number: '9', text: `E conhecerá dos feitos dos Inglezes, no modo que no foral, que de Nós tem, he ordenado.` },
        { id: 'of1-tlii-10', number: '10', text: `Item, conhecerá de quaesquer feitos crimes, ou civeis, em que forem réos, ou autores, o Contador Mór, ou qualquer Contador da dita cidade, Scrivães e Porteiros dos Contos, Juiz da dizima da Alfandega, Thesoureiro, Scrivão, Recebedores, Porteiro e homens della, Scrivães, Enqueredor, Contador e Porteiros do dito Juizo; e outras Justiças não tomarão dos taes feitos conhecimento, pola obrigação, que tem, de residir na dita Alfandega. Porém não poderão os sobredictos Officiaes citar pessoa alguma para o dito Juizo: salvo os moradores, ou stantes na dita cidade, ou seu termo, ou dez legoas ao redor della, sem embargo da Ordenação Livro terceiro, Título 24: Que não julgue Julgador algum em seu feito ou de seus parentes, etc. E de suas sentenças dará appellação para a Casa da Supplicação nos casos, em que se deve dar. E querendo os ditos Officiaes accusar, ou demandar, ou responder em outros Juizos, o poderão fazer. E acontecendo, que citem outros privilegiados, ou delles sejam citados, o autor seguirá o foro do réo: salvo se for a contenda com algum Desembargador, ou Moedeiro, porque os privilegios delles precedem a este, quer sejam autores, quer réos.` },
        { id: 'of1-tlii-11', number: '11', text: `Item, devassará nos casos, que fôrem de devassa, dos casos commettidos das portas a dentro da dita Alfandega, e conhecerá de todos os malefícios hi commettidos; e procederá contra os culpados como for justiça, e das sentenças, que der, appellará para a Casa da Supplicação.` },
        { id: 'of1-tlii-12', number: '12', text: `Item, demandando algumas pessoas perante o dito Ouvidor soldos, ou frêtes, que disserem lhes ser devidos, logo na primeira audiencia perante os réos demandados, ou seus Procuradores, se fôrem presentes, ou á sua revelia, se elles forem citados para a dita audiencia, e nella não parecerem, o dito Ouvidor dará juramento aos autores, se lhes são devidos os ditos soldos, ou frêtes; e jurando que si, fará logo, que os réos ponham em Juizo outro tanto dinheiro, quanto os autores jurarem, e se depositará em mão do Thesoureiro dos depositos do dito Juizo. E fará screver os juramentos, que os ditos autores fizerem, que per elles serão assinados. E sendo o dinheiro assi depositado, ouvirá as partes e procederá nos feitos, como for justiça. E provando os autores tanto, per que os réos devam ser condemnados, o Ouvidor os condenará per suas sentenças, e mandará fazer execução per ellas, tanto que forem passadas pela Chancellaria, se as partes não appellarem, e fará entregar o dinheiro depositado aos ditos autores, com a condenação das custas, que lhes forem julgadas. E achando o Ouvidor que os réos foram mal demandados, e os autores juraram falsamente, além de absolver os réos, condenará sempre os autores nas custas em dobro, e em qualquer outra emenda e satisfação, que lhe parecer, segundo for a malicia; e serão presos, e os autos de suas prisões e dos ditos juramentos serão levados á Relação, para nella lhes ser dada a pena, que merecerem polo juramento. E quanto he ao depositar do dinheiro, o Juiz o cumprirá assi, sem nisso entender a Relação, nem outras algumas Justiças: porquanto ao dito Ouvidor damos todo o poder e alçada para isso nos feitos, que ao dito Juizo pertencem, sob pena de cem cruzados para o Hospital de todos os Santos.` },
        { id: 'of1-tlii-13', number: '13', text: `Item, o Ouvidor da Alfandega terá alçada até oito mil réis. E fará tres audiencias na semana, convém a saber, á segunda feira, quarta e sexta, a horas de vespera.` },
        { id: 'of1-tlii-14', number: '14', text: `E havemos por bem, que os Scrivães do dito Juizo screvam nos feitos dos Hospitaes e Confrarias, que os Mercadores tem em Sancto Spirito e S. Francisco, como sempre fizeram, postoque ao Juiz da dizima da Alfandega seja commettido o conhecimento dos ditos feitos, e a mais administração dos ditos Hospitaes e Confrarias.` },
        { id: 'of1-tlii-15', number: '15', text: `E os Scrivães e Enqueredor do Juizo da Alfandega irão star na dita Casa cada dia pela manhã e á tarde, para hi tirarem as inquirições, e fazerem o que pertencer a seus Officios para bom despacho das partes. E por cada dia que não forem, pagarão hum cruzado, ametade para as despesas do auditorio, e a outra para as partes, que forem desaviadas, não tendo impedimento, que os escuse. E os Porteiros do dito Juizo starão sempre na dita Casa com os Scrivães, para, quando forem requeridos, fazerem as citações, penhoras e execuções.` },
      ],
    },
    {
      id: 'titulo-liii',
      title: `LIII. Do Chanceller das sentenças, dos Corregedores da cidade de Lisboa, Guarda Mór da Torre do Tombo, Ouvidor da Alfandega e Contador da dita cidade`,
      type: 'articles',
      articles: [
        { id: 'of1-tliii-preambulo', number: 'Preâmbulo', text: `O Chanceller, per quem hão de passar as sentenças, e Cartas dos Corregedores da cidade de Lisboa, Juiz da India e Mina, Guarda Mór da Torre do Tombo, Ouvidor da Alfandega, Contador das rendas das Sisas da dita cidade, passará e sellará as ditas Cartas e sentenças a todo tempo, que lhe forem levadas, não sendo em dias, que a Igreja manda guardar, sem para isso ter dias, nem horas limitadas, porque os negocios das partes, que perante os ditos Officiaes correm, não recebem dilação.` },
        { id: 'of1-tliii-1', number: '1', text: `E tendo o Chanceller duvida a passar alguma das ditas Cartas e sentenças, sendo a duvida das que o Chanceller da Casa da Supplicação per seu Regimento pode pôr, guardará a fórma delle, e communicará a duvida com os Corregedores e Ouvidor da Alfandega, e Juiz da Mina, que passaram as Cartas. E conformando-se ambos, e achando que as não devem, nem podem passar, as mandarão romper. E achando que as podem passar, porém que não vão na fórma que devem, as farão emendar, como assentarem que devem ir. E não se concordando, irá tirar a duvida com os Desembargadores do Paço, e o que elles assentarem, se cumprirá. E quanto ás Cartas do Guarda Mór e Contador, em que o Chanceller duvidar (sem as communicar com elles), tirará outrosi as duvidas com os Desembargadores do Paço.` },
        { id: 'of1-tliii-2', number: '2', text: `E levará de cada sentença e Carta, que passar pela Chancellaria, dez réis.` },
      ],
    },
    {
      id: 'titulo-liv',
      title: `LIV. Dos Scrivães, que servem com os Meirinhos da Corte e Alcaides da cidade de Lisboa`,
      type: 'articles',
      articles: [
        { id: 'of1-tliv-preambulo', number: 'Preâmbulo', text: `Os Scrivães, que servem com os Meirinhos da Corte e com os Alcaides da cidade de Lisboa, pousarão na rua, em que pousarem os Meirinhos, ou Alcaides, com quem servirem; e não achando nella casas, pouzarão no mesmo bairro.` },
        { id: 'of1-tliv-1', number: '1', text: `E serão os ditos Scrivães diligentes em servir seus Officios com os ditos Meirinhos e Alcaides nas diligencias, que por bem da justiça, ou a requerimento das partes houverem de fazer. E será cada hum delles obrigado a ir cada dia trez vezes à casa do Meirinho, ou Alcaide, com quem servir, convem a saber, pela manhã, e à huma hora, e ás Ave-Marias; e assi mais todas as vezes que pelos ditos Meirinhos, ou Alcaides fôrem chamados.` },
        { id: 'of1-tliv-2', number: '2', text: `E cada hum dos ditos Meirinhos e Alcaides correrá a cidade, e servirá com o Scrivão, que lhe for ordenado, e não com outro algum: salvo tendo o seu Scrivão tal impedimento, que não possa servir com elle, ou sendo a diligencia, ou negocio, que houver de fazer, de tal qualidade, que haja perigo na tardança, e não tenha tempo para o poder chamar.` },
        { id: 'of1-tliv-3', number: '3', text: `E mandamos, que os ditos Scrivães não vão diante dos Meirinhos e Alcaides, quando de noite correrem a cidade, por se escusarem resistencias, scandalos e outros inconvenientes.` },
        { id: 'of1-tliv-4', number: '4', text: `Os ditos Scrivães não levarão, nem tomarão dos ditos Meirinhos e Alcaides cousa alguma das condenações, que os Julgadores fizerem para os ditos Meirinhos e Alcaides, em quaesquer casos, em que screverem, ou derem suas fés.` },
        { id: 'of1-tliv-5', number: '5', text: `Cada hum dos ditos Scrivães terá hum livro encadernado, numerado e assinado, confórme a Ordenação, per hum dos Corregedores do Crime da Corte, ou da cidade de Lisboa, ou Juizes do Crime della, no qual screverá e assentará todas as condenações verbaes, em que os Julgadores condenarem as pessoas, que lhes forem levadas pelos ditos Meirinhos e Alcaides. E farão assinar as ditas condenações no dito livro pelos Julgadores, que as fizerem, aos quaes mandamos, que as assinem ao tempo, que fizerem as taes condenações.` },
        { id: 'of1-tliv-6', number: '6', text: `De cada auto, que fizerem das condenações verbaes, que assi screverem no livro, que hão de ter, poderão levar oitenta réis: e assi de cada auto de prisão de qualquer pessoa, que os ditos Meirinhos e Alcaides prenderem, que sendo levada perante cada hum dos ditos Julgadores, for mandada per elles à prisão.` },
        { id: 'of1-tliv-7', number: '7', text: `De cada hum dos autos de penhoras e execuções, ou quaesquer outros, que per razão de seus Officios podem fazer, poderão levar oitenta réis à custa das partes executadas. E mais haverão pela ida outro tanto, quanto se montar na metade do que houver de levar o Meirinho, ou Alcaide com quem forem.

q. De cada mandado de soltura de qualquer preso poderão levar vinte réis.` },
        { id: 'of1-tliv-8', number: '9', text: `E qualquer dos ditos Scrivães, que levar mais salario do acima dito, ou não cumprir alguma das ditas cousas aqui declaradas, por cada vez que nisso for comprehendido, além das penas conteúdas nas Ordenações, pagará vinte cruzados, ametade para os Captivos, e a outra para quem o accusar.` },
      ],
    },
    {
      id: 'titulo-lv',
      title: `LV. Dos Sollicitadores da cidade de Lisboa, e Casa do Porto`,
      type: 'articles',
      articles: [
        { id: 'of1-tlv-preambulo', number: 'Preâmbulo', text: `Ordenamos, que na Corte e Casa da Supplicação não haja mais que até vinte Sollicitadores, e na cidade de Lisboa até trinta, e na Casa do Porto dez. Os quaes primeiro que comecem a servir os ditos Officios, serão examinados e approvados, os da Corte e cidade de Lisboa pelo Regedor da Casa da Supplicação; e os da Casa do Porto pelo Governador della. E além de saberem ler e screver, serão casados e bem costumados. E os ditos Regedor e Governador lhes passarão seus mandados para poderem usar dos ditos Officios, e lhes darão juramento dos Sanctos Evangelhos, que bem e verdadeiramente usem dellas. E os farão assentar e screver em hum livro, que para isso haverá em cada huma das ditas Casas, em que se fará assento do juramento de cada hum para que se saiba quantos são, e não possa haver mais que o dito numero.` },
        { id: 'of1-tlv-1', number: '1', text: `E os ditos Sollicitadores não poderão levar mais, que até trezentos réis por mez a cada huma das partes, por quem sollicitarem. E sollicitando mais que tres feitos ou causas, ou negocios da mesma parte, poderão levar mais cem réis, e dahi para baixo levarão aquillo, em que se concertarem com as partes, segundo a qualidade das causas e negocios, não passando dos minaes, e Agente do Correio. ditos trezentos réis por mez, quando sómente sollicitarem até tres feitos, ou negocios, nem de quatrocentos réis, quando forem mais que tres. E levando mais do que dito he, incorrerão nas penas, em que incorrem os Officiaes, que levam mais do conteúdo em seu Regimento.` },
        { id: 'of1-tlv-2', number: '2', text: `E os Sollicitadores da Corte e Casa da Supplicação não poderão sollicitar os feitos e causas, que se tratarem na cidade, nem os da cidade poderão sollicitar as causas, que se tratarem na Corte e Casa da Supplicação, e na Fazenda.` },
        { id: 'of1-tlv-3', number: '3', text: `E se alguma pessoa sollicitar, sem ter os ditos mandados, ou nos Juizos, para que não for ordenado será preso e degradado per hum anno para Africa, e pagará ás partes todo o dano e perda, que por sua causa receberem, e não poderá mais em tempo algum usar do dito Officio. E quando os Sollicitadores stiverem na Relação, ou nas audiencias perante os Julgadores, starão em pé.` },
        { id: 'of1-tlv-4', number: '4', text: `Porém se alguma pessoa, que for presente na Corte, ou na Casa do Porto, ou na cidade de Lisboa, tiver causa sua propria, ou negocio, e o quizer mandar sollicitar e requerer per algum criado, ou familiar seu, ou pessoa chegada á sua casa, podel-o-ha fazer, não sollicitando, nem requerendo outra alguma causa, ou negocio de outra pessoa; e as pessoas que stiverem fóra da Corte, ou da cidade de Lisboa, trazendo demandas nella, ou negocios, ou na Casa da Supplicação, ou do Porto, que se tratarem em sua absencia, podel-as-hão mandar sollicitar e requerer per qualquer Caminheiro, ou pessoa, que venha á isso de fóra, com tanto que o dito Caminheiro, ou pessoa, não sollicite, nem requeira outra alguma causa, ou negocio. E sollicitando os sobreditos criados, ou familiares dos que fôrem presentes, ou as pessoas, que enviarem os que stiverem absentes, outros alguns feitos, ou negocios, incorrerão na pena acima declarada.` },
      ],
    },
    {
      id: 'titulo-lvi',
      title: `LVI. Dos Corredores das folhas das Casas da Supplicação e do Porto, e da cidade de Lisboa`,
      type: 'articles',
      articles: [
        { id: 'of1-tlvi-preambulo', number: 'Preâmbulo', text: `O Corredor das folhas terá cuidado de as correr com muita diligencia per si e não per moços, nem por outras pessoas. E sendo impedido por doença, ou outro algum impedimento, porque o não possa per si fazer, o fará saber, sendo na Casa da Supplicação, ou na cidade de Lisboa, ao Regedor para disso encarregar outra pessoa, que o bem faça: E sendo na Casa do Porto, o fará saber ao Governador della. E se for negligente no correr das folhas, ou correndo-as per outra pessoa sem special mandado do Regedor, ou Governador, Nós faremos do Officio o que nossa mercê fór, e além disso será castigado, como sua culpa merecer: e cada hum delles terá no correr das folhas a maneira, que se dirá no Livro quinto, Titulo 425: Como se correrá a folha dos que forem presos, etc.` },
        { id: 'of1-tlvi-1', number: '1', text: `E tanto que as folhas forem corridas, o Corredor as levará logo ao Scrivão do feito, o qual as ajuntará ao feito, e levará ao Juiz, que delle conhecer, para mandar proceder contra os culpados, segundo as culpas, que nellas lhe saírem.` },
        { id: 'of1-tlvi-2', number: '2', text: `E o dito Corredor irá a todas as audiencias, que na cadea se fizerem aos presos, e terá carrego de citar as partes, a que pertencerem as accusações dos presos pobres, e de chegar as testemunhas, que por parte dos ditos presos, ou da Justiça se houverem de perguntar, e de fazer quaesquer outras diligencias, que cumprirem para bom despacho delles.` },
        { id: 'of1-tlvi-3', number: '3', text: `E o dito Corredor não levará cousa alguma por correr as folhas dos presos, postoque pobres não sejam, porquanto pelo trabalho de as correr e de fazer as ditas diligencias lhe stá ordenado o mantimento, que em cada hum anno ha de haver. E po- derá levar vinte réis de cada folha, que correr de cada seguro, ou pessoa, que sobre fiança ou caução se livrar.` },
        { id: 'of1-tlvi-4', number: '4', text: `E o Corredor da folha da Casa da Supplicação e o da cidade de Lisboa correrão as folhas pelos Scrivães da Corte e da cidade e dos degradados. E o da Casa do Porto as correrá pelos Scrivães do Corregedor do Crime, que anda na dita Casa, e pelos Scrivães da cidade, e não se correrão pelos Scrivães dos Ouvidores do Crime das ditas Relações. E os ditos Corredores serão diligentes no correr das folhas, de modo que dentro em oito dias do dia da prisão, ao mais, seja a folha de todo corrida, e tirada toda a duvida, que houver. E sendo negligente, os Julgadores procederão contra elles com penas pecuniarias e suspensão de seus Oficios, como lhes parecer.` },
        { id: 'of1-tlvi-5', number: '5', text: `E terão os ditos Corredores cuidado de continuar com o Promotor da Justiça, para o livramento dos presos correr com mais brevidade. E ser-lhes-ha pago ordenado com certidão do dito Promotor de como servem bem seus Oficios, e sem ella não.` },
        { id: 'of1-tlvi-6', number: '6', text: `E não cumprindo o dito Corredor o que acima dito he, incorrerá em pena de mil réis por cada vez, ametade para o preso, que assi retardar, ou de que levar dinheiro, e a outra para as despesas da Relação. E sendo a culpa, ou negligencia tal, que pareça ao Regedor, ou Governador, ou aos Julgadores, que merece mór castigo, além da dita condenação, o poderá cada hum delles suspender do dito Oficio pelo tempo, que lhe bem parecer.` },
      ],
    },
    {
      id: 'titulo-lvii',
      title: `LVII. Que os Scrivães e Meirinhos e outros Officiaes tenham armas e cavallos`,
      type: 'articles',
      articles: [
        { id: 'of1-tlvii-preambulo', number: 'Preâmbulo', text: `Ordenamos que todos os Tabelliães das Notas e Judicial de todas as cidades, villas e lugares de nossos Reinos, Juizes dos Orfãos e Scrivães das Cameras perpetuos, ou a tempo limitado, e Scrivães dos Orfãos e Almotaçaria, e Scrivães dante os Corregedores das Comarcas e Chancelleres dante elles, Alcaides, Meirinhos das ditas Correições, e Scrivães de ambas as Casas, assi da Supplicação como do Porto (tirando os que tiverem de Nós moradias assentadas em nossos Livros, e que ainda agora lhes sejam pagas), Scrivães dante os Ouvidores dos Mestrados e de Senhores de terras e de Fidalgos, que jurisdição tiverem, e Meirinhos dante elles: cada hum destes seja obrigado a ter, e tenha continuadamente comsigo couraças e capacete, lança e adarga, para quando cumprir nas cousas de seus Oficios e por bem da Justiça com as ditas armas servirem, ou em qualquer outra cousa, em que por nosso serviço lho mandarmos. E nesta mesma maneira serão obrigados a ter as ditas armas os nossos Almoxarifes dos Almoxarifados de todo o Reino e Scrivães delles, e os Recebedores das casas da arrecadação de nossos Direitos em a cidade de Lisboa, e em quaesquer outras cidades, villas e lugares, em que as ditas recebedorias por Oficio tenham, e assi os Scrivães das ditas Casas e recebedorias, e Scrivães das Sisas e feitos dellas, Alcaides das saccas, e o Contador dos Contos da dita cidade e Scrivão delle, e Vedor das obras da cidade e Scrivão do Thesouro della, e Scrivães dos nossos Contos das Comarcas, e os Corretores da cidade de Lisboa e do Porto, e Scrivães da Moeda das mesmas cidades, e outros nossos Officiaes das ditas Moedas, que de Nós mantimento tiverem, sob pena de qualquer destes, assi da Justiça, como da Fazenda, aqui declarados, que as ditas armas não tiver, perder por o mesmo caso seu Officio, para o darmos a quem houvermos por bem.` },
        { id: 'of1-tlvii-1', number: '1', text: `E havemos por bem, que sendo-lhes provado como não tem as ditas armas, lhes possam por isso ser pedidos os Officios, como por qualquer outro erro, que nelles façam, por que com direito os devam perder, dos quaes faremos mercê per nossas Cartas de se assi he, ás pessoas, que polo dito erro os pedirem, sendo taes, que nelles caibam, provando elles como os ditos Officiaes não tem as ditas armas. E sendo pessoas, em que não caibam, lhes faremos mercê de dinheiro, que nos bem parecer.` },
        { id: 'of1-tlvii-2', number: '2', text: `E bem assi mandamos, que os Scrivães da Casa da Supplicação e do Porto, e os das correições, e os Tabelliães da cidade de Lisboa, Evora, Coimbra, Porto, Lamego, Viseu, Guarda, Tavira, Lagos, Faro, Silves, Béja, Elvas, Portalegre, Leiroa, Bragança, Santarem, Olivença, Estremoz, Moura, Serpa, Campo Maior, Arroncheç, Monte Mór o Novo, Guimarães, Barcellos, Chaves, Villa Real, Covilhã, Torres Vedras, Crato, Abrantes, Thomar, Torres-Novas, Castel-Branco, Nisa, Fronteira, Loulé, Villa nova de Portimão, Setuval, Alcacer, Mertola, Almoudovar, Mecejana, Ourique, Aljustrel, assi do Judicial como das Notas, e os Scrivães das Ouvidorias dos Mestrados, tenham além das ditas armas, continuadamente cavallos sob as penas sobreditas. E vendendo-os, ou morrendo-lhes, serão obrigados a haver outros dentro de tres mezes, que se entenderão per todo hum anno, ora os vendam muitas vezes, ora huma, sob as ditas penas.` },
      ],
    },
    {
      id: 'titulo-lviii',
      title: `LVIII. Dos Corregedores das Comarcas`,
      type: 'articles',
      articles: [
        { id: 'of1-tlviii-preambulo', number: 'Preâmbulo', text: `O Corregedor da Comarca, tanto que for em sua correição, mandará aos Tabelliães do lugar, para onde houver de ir, que lhe enviem as culpas, querelas e stados, que tiverem de quaesquer pessoas, que sejam obrigadas à Justiça.` },
        { id: 'of1-tlviii-1', number: '1', text: `E quando os Tabelliães não tiverem enviadas as culpas ao Corregedor, antes que venha ao dito lugar, por lhas elle não mandar pedir, dar-lhas-hão do dia, que chegar, a tres dias, scriptas e assinadas per suas mãos, e não per letra de outrem. E o Corregedor as verá; e os que achar em taes culpas, por que devam ser presos, mandará per seus Alvarás aos Juizes e Alcaides do lugar, onde stiverem os malfeitores, que os prendam. E se algum não for preso por culpa desses Juizes, ou Alcaides, procederá contra elles como for direito. E se alguns Tabelliães lhe sonegarem alguma querela, inquirição, ou outro auto, que a bem de Justiça pertença, quando assi o Corregedor vindo ao lugar lhas mandar pedir, ou as não dér todas nos ditos tres dias, procederá contra elles a privação dos Officios, e qualquer outra pena, que per Direito merecerem. E para certeza de como lhas mostraram, o Tabelliào, ou Scrivão fará hum rol, conforme ao que se dirá no Titulo 79: Dos Tabelliães do Judicial.` },
        { id: 'of1-tlviii-2', number: '2', text: `E tanto que for no lugar, mandará aos Juizes e Tabelliães, que lhe mostrem as inquirições devassas, que hi houver, e deve-as ver logo. E se alguns dos conteúdos nellas forem livres pelos Juizes do lugar, saberá como os desembargaram. E se achar que o livramento foi per conluio, ou falsa prova, fal-o-ha emendar, em maneira que se faça logo direito, e não pereça a Justiça. E achando que os Juizes, ou outros alguns são culpados em esse conluio, por a sentença ser dada per peita, affeição, ou per outro modo maliciosamente, proceda contra elles, segundo a culpa de cada hum. E terá nisso a maneira, que diremos no Livro quinto, no Titulo 130: Quando o que foi livre per sentença de algum crime, etc.` },
        { id: 'of1-tlviii-3', number: '3', text: `Outrosi terá cuidado de saber, que Tabelliães ha em cada Villa e Julgado de sua correição, e se sabem fazer bem seu Officio, e se usam delle como devem. E achando que algum por seu máo ler e screver, ou outra inhabilidade, não he sufficiciente para servir o tal Officio, o suspenda delle, e lhe assine termo, a que appareça perante os Desembargadores do Paço, aos quaes enviará dizer seus defeitos, e a causa, porque o suspendeu, para elles o examinarem, e proverem nisso como for direito. E se o dito Corregedor achar que algum usa mal de seu Officio, proceda contra elle, e lhe dê a pena que per Direito merecer, dando appellação e aggravo para o Juiz da Chancellaria nos casos que deve. E achando que em alguns desses lugares são necessarios mais Tabelliães, nol-o faça saber, declarando-nos algumas pessoas, que nesses lugares houver para isso mais pertencentes, para Nós sobre isso provermos, como nos bem parecer. O que fará, assi nas nossas terras como nas das Ordens, e de outras quaesquer, que jurisdições e Tabelliados tiverem, onde per bem de seu Officio devem entrar.` },
        { id: 'of1-tlviii-4', number: '4', text: `E tanto que chegar a cada lugar de sua correição, saberá se he necessario fazer-se eleição dos Juizes e Officiaes do Concelho. E terá nisso a maneira, que diremos neste Livro, no Título 67: Em que modo se fará a eleição, etc.` },
        { id: 'of1-tlviii-5', number: '5', text: `Item, saberá pela inquirição, que cada anno se ha de tirar sobre os Officiaes da Justiça, se os Juizes Ordinarios fizeram as audiencias ordenadas nos feitos dos presos, como lhes he mandado, e se desembargaram seus feitos sem delonga. E se mandaram soltar alguns, não appellando por parte da Justiça nos casos, em que são obrigados a appellar, ainda que as partes não appellem. E em tal caso elle appellará por parte da Justiça para os Julgadores a que pertencer. E contra os que achar culpados nestas cousas, e em quaesquer outras, que a seus Officios pertençam, proceda como for direito.` },
        { id: 'of1-tlviii-6', number: '6', text: `E mandará pregoar, que venham perante elle os que se sentirem aggravados dos Juizes, Procuradores, Alcaides, Tabelliães, ou de poderosos e de outros quaesquer, e que lhes fará cumprimento de direito. E que assi venham perante elle todos os que tiverem demandas, e que lh'as fará desembargar. E dado assi o pregão, mandará chamar os Juizes, e pol-os-ha a par de si, e far-lhes-ha pergunta, quando vierem as partes, que feitos tem perante elles, assi civeis, como crimes, e o por que os não despacham, mandando-lhes que logo os desembargues, mostrando-lhes o como os hão de despachar.` },
        { id: 'of1-tlviii-7', number: '7', text: `E em cada hum lugar de sua Comarca mandará pregoar, que nenhum encubra, nem colha degradado, nem ladrão nem outro malfeitor, nem receba furto algum em sua casa. E que áquelle, que fizer, lhe será dada a pena, que per Direito merecer.` },
        { id: 'of1-tlviii-8', number: '8', text: `E saberá se os Juizes tem cuidado de saber se os Tabelliães guardam o Regimento, que da Chancellaria levaram e juraram: e achando que os ditos Juizes em isto são negligentes, proceda contra elles segundo suas culpas. E assi mesmo contra os Tabelliães, que achar culpados dando-lhes aquellas penas, que em nossas Ordenações e em seus Regimentos são conteúdas.` },
        { id: 'of1-tlviii-9', number: '9', text: `E saberá se ha hi competencias, ou bandos em cada hum dos lugares, em que ha de fazer correição, e quaes são os principaes delles, e se dessas competencias, ou bandos se seguem pelejas, voltas, mortes, ou outros males e danos. E havendo-os hi, procederá contra elles, como for direito, segundo o caso for. E além disso sendo de qualidade, que nol-o deva fazer saber o fará.` },
        { id: 'of1-tlviii-10', number: '10', text: `Outrosi saberá, se os daquelle lugar onde fizer correição, recebem aggravos dos Almoxarifes e Scrivães, ou dos Porteiros, Saccadores, ou de outros quaesquer Officiaes, que hajam de tirar e procurar nossos Direitos, aggravando o povo, como não devem. E se for per razão de seus Officios, diga-lhes que o não façam; e perseverando elles, faça-lho emendar, não conhecendo porém dos feitos; e depois de emendado, faça-o saber a Nós. E isto se entenda, quando no lugar, onde isto acontecer, não stiver Vedôr da Fazenda ou Contador, a que pertence; porque se hi stiver, lhe notificará o que se assi faz, para que proveja nisso, como seja emendado.` },
        { id: 'of1-tlviii-11', number: '11', text: `E deve saber se alguns poderosos, ou outras pessoas embargam nossos Direitos, ou os retem sem razão, e fará logo, que se recadem para Nós.` },
        { id: 'of1-tlviii-12', number: '12', text: `E se alguns Concelhos tem demandas, ou contendas entre si, deve trabalhar, quanto podér, de os concertar e avir, e não podendo, faça-o saber a Nós: e envie-nos dizer o caso como he, e a causa, donde nasce, e o dano, que disto póde recrescer, e aquillo que entender que he bem fazer-se, e a razão, que o a isso move.` },
        { id: 'of1-tlviii-13', number: '13', text: `E entrará em os Castellos, assi nossos como das Ordens, e verá como são bastecidos de armas e das mais cousas que Estes actos estabelecem providencias contra os jogos de pedrada, entrudos, e arrumamentos de carros nas ruas e praças.

lhes forem necessarias: e se as Torres e muros hão mister concerto e repairo. E o mesmo saberá das cercas das Villas. E todo o que achar, nol-o fará saber. E mandamos aos Alcaides, que tem os Castellos, que lhe deixem ver as cousas acima ditas. E guardará ácerca disso o que se contém no Titulo 74: Dos Alcaides Móres, no paragrapho 14: E os Juizes.` },
        { id: 'of1-tlviii-14', number: '14', text: `E bem assi saberá, se as prisões de cada hum lugar são taes como cumpre, de maneira que os presos possam ser nellas bem guardados. E se taes não forem, mande-as fazer aquelles, que forem a isso obrigados, assi aos nossos Oficiaes, como a outros quaesquer. E faça que os homens, que houverem de guardar as prisões, sejam de boa fama e costumes, e arreigados na terra; e avise-os, que guardem bem os presos, e que sejam certos, que se lhes fugirem, lhes será dada grave pena. A qual será dada aos que assi o não fizerem, como per nossas Ordenações e Direito he determinado.` },
        { id: 'of1-tlviii-15', number: '15', text: `Outrosi verá os Foraes de cada lugar para ver se nos tomam algum Direito, que nos pertença haver per elles, ou se lhes imos contra seu foro. E saberá se nos tomam nossos Direitos, que nos pertence haver, assi das herdades, como das jurisdições, usando dellas, como não devem segundo diremos no segundo Livro, Titulo 45: Em que maneira os Senhores de terras, etc. E emendará o que per si poder; e o que per si não poder emendar, nol-o serverá. E isso mesmo faça, se Nós lhe levarmos alguma cousa do seu sem razão.` },
        { id: 'of1-tlviii-16', number: '16', text: `E assi saberá em que quantia os Juizes e Vereadores deixaram as rendas do Concelho, e quanto rendem ao tal tempo. E se menos renderem, saiba qual he a razão. E achando que he por culpa dos ditos Oficiaes, proceda contra elles, como per direito deve.` },
        { id: 'of1-tlviii-17', number: '17', text: `E informar-se-ha ex officio, se ha nas Cameras algumas posturas prejudiciaes ao povo e ao bem comum, postoque sejam feitas com a solemnidade devida, e nos serverá sobre ellas com seu parecer. E achando que algumas não foram feitas, guardada a fórma de nossas Ordenações, as declarará por nullas e mandará que se não guardem.` },
        { id: 'of1-tlviii-18', number: '18', text: `Item, se nos lugares de sua Comarca houver alguns Clerigos revoltosos e travessos, o fará notificar aos Prelados para que os castiguem; e não o querendo elles fazer, nol-o fará saber, para nisso provermos, como nos bem e justiça parecer.` },
        { id: 'of1-tlviii-19', number: '19', text: `E nos feitos dos livramentos, que procederem das correições, que o Corregedor he obrigado fazer, screverão os Scrivães dante elle, e leval-os-hão comsigo, aindaque o Corregedor ande pela Comarca. E assi screverão nos mais casos, que per nossas Leis lhes pertencem, ou que per Provisões particulares lhes forem commetidos, postoque os culpados sejam Tabelliães, ou outros Oficiaes quaesquer de Justiça: E assi nos feitos civeis e causas das pessoas poderosas, de que per bem desta Ordenação os Corregedores são Juizes. E os que não forem das devassas das correições, nem das que tirarem per nossas Provisões, os deixarão na terra. E nos casos, em que os Corregedores conhecem stando no lugar, por os Juizes de fóra serem suspeitos, ou absentes, ou por nelle não haver Juiz de fóra, screverão os Tabelliães e Scrivães do Judicial.` },
        { id: 'of1-tlviii-20', number: '20', text: `Item, não trará comsigo cadea de correição pelos lugares pequenos, em que não houver casas fortes de cadeas, e os delinquentes, que prender por culpas leves quando se partir do lugar deixará na cadea delle. E sendo os casos graves, ou elles de tal qualidade, de criação ou parentesco, que verisimilmente se receê de serem tirados, ou fugirem, quando do tal lugar se partir, os mandará à cadea de sua correição, ou a um castello, ou outras cadeas fortes dos lugares mais Comarcãos de sua correição, em que lhe pareça, que starão mais seguros: para o que poderá constranger os Juizes, que lhe dêm homens do Concelho, para irem em guarda dos presos. E o mesmo fará, quando lhe parecer necessario por fraqueza da prisão, em que stiverem. E mandamos aos Alcaides dos Castellos e Carcereiros das cadeas, que recebam os ditos presos, quando lhes forem mandados pelo Corregedor. E o Alcaide, que os não receber no Castello será emprazado, que em vinte dias venha em pessoa à Corte, para lhe ser dada a pena, que per direito merecer. E os Carcereiros, que não cumprirem o que lhes fora mandado, pagarão quatro mil reis para con- certo das cadeas da correição, da qual pena o Chanceller da correição será executor, sob pena de perder o Officio.

De que feitos conhecerá.` },
        { id: 'of1-tlviii-21', number: '21', text: `O Corregedor da Comarca não mandará citar pessoa alguma, que stiver no lugar, ou termo, onde elle stiver, per mandados, senão per Porteiro, segundo fórma de nossas Ordenações.` },
        { id: 'of1-tlviii-22', number: '22', text: `E o dito Corregedor não conhecerá per auçâo nova, nem avocará feito algum crime, nem civel, salvo os feitos e causas dos Juizes, Alcaides, Procuradores, Tabelliáes, Fidalgos, Abbades e Priores, nos casos, de que a jurisdição direitamente pertence a Nós, os quaes per nossas Ordenações são declarados. E bem assi de outras quaesquer pessoas poderosas, de que lhe parecer, que os Juizes da terra não farão inteiramente justiça, e dos feitos e causas, em que os Juizes das terras forem suspeitos; porque de todos estes sobreditos poderá conhecer, em quanto stiver no lugar, assi per auçâo nova, como avocando-os, se lhe parecer necessario, postoque os Juizes da terra digam, que farão delles justiça, quer sejam autores, quer réos, o que se entenderá, postoque nos taes lugares haja Juizes de fóra.` },
        { id: 'of1-tlviii-23', number: '23', text: `E conhecerá outrosi por auçâo nova, de duas legoas sómente de lugar ao lugar onde stiver, de quaesquer casos, não sendo das Cidades, ou Villas, onde houver Juizes de fóra. E poderá avocar a si os feitos, que pela dita maneira nellas houver, e os processará, e determinará finalmente, confórme a alçada, que de Nós tiver. E destes feitos, de que assi conhecer per auçâo nova, não se pagará dizima, nem direito algum, sómente o que se houvera de pagar delles, se os Juizes ordinarios os processaram e determinaram. E para se saber de quaes feitos se ha de pagar dizima, ou não, quando houverem de ir per appellação, fará o dito Corregedor pôr no começo delles a razão, que teve para conhecer delles per auçâo nova.` },
        { id: 'of1-tlviii-24', number: '24', text: `E quando se o Corregedor quizer partir do lugar e Julgado, onde pelo dito modo conhecer dos taes feitos, os deixará todos no dito lugar e Julgado aos Juizes da terra, e sendo suspeitos, a hum homem bom della. Porém se ao Corregedor parecer, que alguns dos ditos feitos são de taes pessoas, que os Juizes da terra, ou aquelles, a que os devia deixar, não poderão fazer delles justiça, levalos-ha comsigo, onde quer que for, até acabar de dar nelles livramento: salvo se o menos poderoso dos litigantes, quer seja autor, quer réo, quizer antes que o feito fique na terra, porque então o deixará nella. E isto não haverá lugar nos feitos dos Juizes, Procuradores, Tabelliáes, Alcaides e outros Officiaes da Justiça do mesmo lugar: porque estes ficarão na terra, postoque o Corregedor os queira comsigo levar, e as partes contrarias lhe requeiram que os leve. E quando o Corregedor tornar pelo dito lugar, se achar que alguns daquelles feitos não são desembargados por culpa, ou malicia dos Juizes, a que os deixou, proceda contra elles como for justiça. Porém os feitos do livramento dos ditos Officiaes culpados na devassa poderá levar comsigo e sentenciai-os, como diremos no paragrapho 34: E bem assi, deste Titulo.` },
        { id: 'of1-tlviii-25', number: '25', text: `Item, não conhecerá per appellação de feito algum: e conhecerá dos instrumentos de aggravo, ou Cartas testemunhaveis, que da correição a elle vierem, de que os Desembargadores dos Aggravos ou os Corregedores do Crime da Corte e da Casa do Porto podem conhecer: E isto não cabendo as causas na alçada dos Juizes de que se aggravarem, porque cabendo nella o Corregedor não proverá os aggravantes, sómente dirá que os não provê, por caber a causa na alcada dos Juizes. Porém sendo o aggravo sobre incompetência do Juizo, ou sobre nullidade notória, poderá tomar conhecimento dos taes aggravos postoque a causa caiba na alçada dos Juizes, de que se aggrava, e dar determinação como lhe parecer justiça. E todo o acima dito se entenderá, com tanto que as partes declarem, que aggravam para elle, porque não fazendo esta declaração, não tomará conhecimento de tal aggravo. E assi no lugar, onde stiver, poderá conhecer dos ditos aggravos, mandando levar os feitos perante si, pelas petições, que lhe as partes fizerem. E o mesmo fará pelas petições de aggravo, que lhe fizerem de dentro das cinco legoas do lugar, onde stiver, e dos lugares do termo, posto que o lugar seja mais afastado das cinco legoas. E sendo os aggravos de fóra das cinco legoas, ou de fóra do termo, não mandará ir os proprios feitos, mas as partes tirarão instrumentos de aggravo com respostas, e em todos os ditos aggravos dará determinação se são aggravados, ou não. E des que nos ditos aggravos der determinação, mandará tornar os feitos aos Juizes, para os processarem.` },
        { id: 'of1-tlviii-26', number: '26', text: `Porém não conhecerá de aggravos alguns de injurias verbaes, nem do que per nossas Ordenações he determinado, que pertence à Camera sem appellação nem aggravo.` },
        { id: 'of1-tlviii-27', number: '27', text: `Nem conhecerá de feitos, que a elle venham per maneira de aggravo, de quaesquer sentenças definitivas, que pelos Juizes da terra forem dadas, para tomar conhecimento dos merecimentos da causa, e determinar, se foi bem, ou mal julgado. Mas poderá conhecer e determinar, se he caso de appellação, quando sómente pelo Juiz for denegada; e mandar-lhe-ha que a receba, e que assine tempo às partes, em que a vão seguir perante os Julgadores, a que o conhecimento della pertencer. E quando o aggravo for de o Juiz não receber appellação de sentença interlocutoria, aindaque tenha força de definitiva, guardará o que diremos no terceiro Livro, no Titulo 69: Das appellações das sentenças interlocutorias. E quando o aggravo for de o Juiz receber appellações, quer de sentença definitiva, quer interlocutoria, à parte contraria, não conhecerá de taes instrumentos, ou Cartas testemunhaveis; porque o conhecimento dos ditos aggravos pertence aos Desembargadores dos Aggravos.` },
        { id: 'of1-tlviii-28', number: '23', text: `Item, será obrigado fazer audiencias às partes tres dias em cada semana nos lugares publicos para ello ordenados.` },
        { id: 'of1-tlviii-29', number: '29', text: `E quando lhe for offerecida alguma Carta, ou perdão pela parte, não mandará fazer disso Alvará, que se cumpra sómente per sua mão porá nas costas da tal Carta: Cumpra-se, se assi lhe parecer que com justiça se deve fazer. E das outras Cartas, ou mandados, que forem dirigidos para outros Julgadores, ou sentenças de cada huma das Relações, postoque pelas partes sejam presentadas ao dito Corregedor, e requerido que lhas mande cumprir, elle o não fará, nem mandará fazer Mandado, nem Alvará algum para se cumprir, antes dirá às partes, que lhos assi presentarem, que os levem às Justiças, a que forem dirigidos; e quando os não cumprirem, se vão a elle dito Corregedor, e elle os mandará então cumprir, e os castigará como achar que for justiça.` },
        { id: 'of1-tlviii-30', number: '30', text: `Outrosi mandamos a todos os Corregedores das Comarcas, e a quaesquer outros Julgadores, que tanto que os feitos dos presos forem sentenciados, de que as appellações devam vir a cada huma das Relações, a que pertencerem, os façam traslatar, cerrar e sellar, segundo diremos no terceiro livro, no Titulo 70: Das appellações das sentenças definitivas; e sem guardarem o despacho dos Caminheiros, as enviem per quaesquer pessoas sem suspeita, que lhes por parte dos presos forem presentadas, tomando-lhes primeiro juramento, que bem e fielmente as tragam, e presentem aos Officiaes, a que devem ser entregues, e levem delles seus conhecimentos. E quando as semelhantes pessoas as trouxerem, os Caminheiros não levarão cousa alguma. E os Corregedores das Comarcas e os outros Julgadores, que o assi não cumprirem, sejam suspensos dos Officios até nossa mercê, e paguem dez cruzados, ametade para quem os accusar, e a outra para o preso.

Devassas.` },
        { id: 'of1-tlviii-31', number: '31', text: `E cada hum Corregedor em sua Comarca saberá em cada mez per inquirição devassa, assi per os presos, como per outras pessoas, se os Carcereiros levam peitas dos presos, ou de outras pessoas per respeito delles, por lhes deitar E no versiculo — por lhes deitar menos prisão, — parece haver sido, segundo o dito Gordo, derivada do mesmo Codigo liv. 1 t. 27 § 9, por guardar analogia entre o Carcereiro da Corte, de que se trata neste titulo, e os das cidades e villas.

menos prisão do que seus delictos merecem; e se achar alguns culpados, faça-os prender, e fazer delles justiça.` },
        { id: 'of1-tlviii-32', number: '32', text: `Outrosi saiba per inquirição nos lugares, onde ha Mosteiros de Freiras, ou Donas, se alguns homens tem nelles conversação illicita, ou são infamados com algumas dellas: e defenda-lhes, que não vão mais a elles de noite nem de dia. E os que achar, que lá mais vão depois da dita defesa, sejam degradados dessa Correição até nossa mercê. E se fôrem de pegue na condição, mande-os prender, e envie-nos a defesa, que lhes fez, e as inquirições, que tiver contra elles, para lhes darmos a pena, que houvermos por bem: e deixe mandado aos Juizes, que assi o façam. Porém se per prova certa achar alguns culpados com Freiras, ou Donas desses Mosteiros, proceda contra elles, dando-lhes as penas, que per nossas Ordenações merecerem.` },
        { id: 'of1-tlviii-33', number: '33', text: `E quando fizer correição, se informará nos lugares, em que a fizer, se ha nelles Medicos, que curem de Medicina, ou Cirurgiães, ou Sangradores, ou pessoas outras, que curem de Cirurgia, ou que sangrem, e quantos são, e os mandará vir todos perante si, e os constrangerá mostrar as Cartas de seus gráos, ou Provisões, per que curam, ou sangram. E não lhas mostrando, e contando-lhe per summario de testemunhas, que curam, ou sangram, fará disso autos, e os emprazará, que em certo termo conveniente, que lhes assinará, se presentem na Corte, os Medicos perante o Fisico Mór, e os Cirurgiães e Sangradores perante o Cirurgião Mór, para se livrarem da culpa, que nisso tiverem; aos quaes enviarão o traslado dos autos, para procederem contra elles confórme a seus Regimentos.` },
        { id: 'of1-tlviii-34', number: '34', text: `E bem assi inquirira, quando chegar a cada hum lugar de sua correição, huma só vez em cada anno, sobre os Juizes ordinarios, Juizes dos Orphãos, Juizes das Sizas, Scrivães dellas, Procuradores, Meirinhos, Alcaides, Tabelliães, Coudeis Ordena-se o receituario em portuguez, prohibe-se aos Medicos e Cirurgiães a venda de remedios, e receitar com Boticario rarente.

e quaesquer outros Officiaes de Justiça e dos Concelhos dos lugares de suas correições, per onde andarem. E bem assi sobre os Alcaides das saccas e Officiaes dante elles para saberem se usam de seus Officios, como devem, e cumprem o que são obrigados, e per seus Regimentos lhes he mandado. E bem assi se os Scrivães dão menos da quarta parte do salario ás pessoas, que os ajudam a screver. E na dita inquirição perguntará sómente pelos erros e culpas, que os ditos Officiaes tiverem commettido naquelle anno, em que se tira a devassa, e no outro atraz, e mais não. E contra os culpados procederá, sentenciando seus processos, como for direito, dando appellação e aggravo nos casos, em que couber. E qualquer Corregedor, que as ditas inquirições não tirar, seja suspenso até nossa mercê, e mais pague dez mil réis para quem o accusar.` },
        { id: 'of1-tlviii-35', number: '35', text: `Item, devassará cada anno dos passadores dos lugares de suas Comarcas, e sobre as pessoas, que lhes dão ajuda e favor. E bem assi dos que tiram ouro, ou prata amoedada, ou por moedar, nos portos de mar de suas correições. E os Corregedores das Comarcas de Santarem e Thomar, e o Ouvidor do Mestrado na Comarca de Setuval, nos lugares, que stiverem dentro das dez legoas, ou fóra dellas, duas legoas, ao longo do Tejo, devassarão dos que compram pão para revender, ou o atravessam. E o Ouvidor de Setuval nos mezes de Março e Setembro devassará geralmente das pessoas, que nos lugares de Riba-Tejo; ou nos caminhos atravessam o pão, que vem para Lisboa, postoque seja para padejar, ou para despesa de suas casas.

Prisões.` },
        { id: 'of1-tlviii-36', number: '36', text: `E o dito Corregedor não mandará prender pessoa alguma, senão pelos Meirinhos, Alcaides, Quadrilheiros, e pelos Juizes dos lugares. E quando mandará prender algumas pessoas per seus Agarites, os passará na fórma, que diremos no Livro quinto Titulo 419: Como serão presos os malfeitores.` },
        { id: 'of1-tlviii-37', number: '37', text: `E quando mandar prender algum malfeitor per seus Meirinhos fóra do lugar e termo, onde stiver, não lhes consentirá que levem os homens de hum Concelho para outro sem seu special mandado.` },
        { id: 'of1-tlviii-38', number: '38', text: `E mandará prender os que devem ser presos por culpas, que lhe forem dadas. E presos os remetterá aos Juizes com suas querelas, denunciações e informações mandando-lhes, que os desembarguem como for direito. E lhes dará per scripto quantos e quaes, e porque razão são presos, para saber o despacho e diligencia dos Juizes: salvo se forem das pessoas sobreditas, de que elle ha de tomar conhecimento: como dito he atraz no paragrapho 22: E o dito Corregedor não conhecer per ação nova. E bem assi os ladrões, ou outros malfeitores, que elle Corregedor per si, ou seus Officiaes prender, que pela qualidade de seus casos mereçam morte natural, ou civil, ou de outros casos graves, não remetterá em maneira alguma aos lugares, onde commetteram os delictos, postoque, as Justiças delles lhos enviem pedir, e as partes danificadas, ou os mesmos presos lho requeiram: mas os terá nas cadeas da correição a bom recado, e tomará conhecimento de seus feitos, postoque seja per ação nova; e os despachará com toda a brevidade. Porém, se algum dos ditos malfeitores for preso na jurisdição, onde houver algum Juiz de fóra per Nós, e for per elle requerido, ser-lhe-ha per elle remettido, se na dita sua jurisdição commetteu o delicto. E os outros malfeitores, que não prender, em quanto hi stiver, os dará em scripto aos Juizes daquelle lugar perante hum, ou dous Tabelliães, e mandar-lhes-ha que os prendam, e ouçam, e desembarguem, como for direito. E mandará aos Tabelliães, que se os Juizes depois os não quizerem prender, nem trabalhar por isso, sabendo onde stão, o scrervam assi em seus livros de maneira, que per elles o dito Corregedor, ou o nosso Corregedor da Corte, quando formos per hi, sejam certos da obra, que os Juizes sobre ello fizeram, para lhes ser estranhado segundo suas culpas.` },
        { id: 'of1-tlviii-39', number: '39', text: `E porque alguns malfeitores se achegam a algumas pessoas poderosas, e se acolhem as suas casas, por as Justiças os não prenderem, nem se fazer delles cumprimento de direito, mandamos ao Corregedor, que seja nisso diligente, e trabalhe elle e os Juizes por os prenderem, em quaesquer lugares e casas, onde forem achados guardando ácerca disto a Ordenação do quinto Livro, no Titulo 104: Que os Prelados e Fidalgos não acoutem malfeitores.

Cartas de seguro.` },
        { id: 'of1-tlviii-40', number: '40', text: `E dará todas as Cartas de seguro em sua correição aos que lhas pedirem, e irão dirigidas para os Juizes das terras. As quaes porém não passará em caso de morte de homem, traição, aleive, sodomia, moeda falsa, tirada de presos da cadea, offensa, ou resistencia feita a Official de Justiça, que pertence aos Corregedores da Corte, nem de erros de Tabellião, que se diga ter commettidos em seu Officio, e de outros Officiaes, de que o conhecimento pertencer ao Juiz da Chancellaria. E as cartas de seguro, que assi o dito Corregedor pode dar, não dará no lugar, onde stiver o Corregedor da Côrte.` },
        { id: 'of1-tlviii-41', number: '41', text: `E para saber se os Juizes desembarguam os feitos dos seguros, como devem, o Corregedor terá seu livro, em que ponha todas as Cartas de seguro, que der para os Juizes de cada lugar, e o dia, em que hão de apparecer perante elles, para ver, quando for per esses lugares, se os que as Cartas tomaram, appareceram perante os Juizes nesses feitos.

Bemfeitorias.` },
        { id: 'of1-tlviii-42', number: '42', text: `E achando na sua correição alguns lugares despovoados, saberá porque se despovoaram, e per que modo se melhor poderão povoar. E faça-o saber a Nós, para mandarmos o que for nosso serviço.` },
        { id: 'of1-tlviii-43', number: '43', text: `E mandará que se façam as bemfeitorias publicas, calçadas, pontes, fontes, poços, chafarizes, caminhos, casas do Concelho, picotas, e outras bemfeitorias, que forem necessarias, mandando logo fazer as que cumprir de novo serem feitas, e repairar as que houverem mister repairo: o que todo fará das rendas do Concelho. E sendo os danificamentos por negligencia dos Vereadores, os fará emendar per seus bens. E quando não houver dinheiro do Concelho, e houver necessidade de finta para o dito caso, ou para outros, que lhe pareçam necessarios, poderá mandar fintar até quantia de quatro mil réis. E sendo necessario mais, nol-o fará saber, para Nós lhe darmos a provisão, que nos bem parecer, sem a qual em nenhum caso dará licença para fintar.` },
        { id: 'of1-tlviii-44', number: '44', text: `E as Cartas de finta, que assi póde passar, mandará registrar em hum livro que na Chancellaria de cada correição andará, feito pelo Scrivão della, e não levará cousa alguma pelo registro. E nas costas da Carta porá como fica registrada, e assinará no dito assento, e o Corregedor não assinará a dita Carta, sem ver o registro. E quando alguma cidade, villa, lugar, ou Concelho, mandar pedir as ditas Cartas, sempre se verá pelo registro para que cousa pede a finta, a qual não passará, sem ser certo per certidão do Juiz, Vereadores e procurador do Concelho, como a outra finta, para que lhe deu licença foi tirada, e tomada a conta da despeza della, e achou que foi despesa no para que foi pedida. E se for terra chã, em que não houver Juiz, nem Vereadores, virá a certidão scripta pelo Scrivão da Camera, e não o havendo, per tres homens bons do Concelho. E emquanto o dinheiro da finta não for de todo tirado, e bem despesa no para que a pediram, não dará outra de novo.` },
        { id: 'of1-tlviii-45', number: '45', text: `E nas outras fintas, que passarem da quantia de quatro mil réis, quando os Officiaes das Cameras as houverem de pedir, o screverão ao Corregedor da Comarca, como a querem pedir, e a necessidade, que della tem, e para que cousas. O qual Corregedor guardará a ordem, que diremos no Título 66: Dos Vereadores.` },
        { id: 'of1-tlviii-46', number: '46', text: `E nos lugares, em que fôr necessario, e para isso forem dispostos, mandará pôr quaesquer arvores de fructo, que se em elles poderem dar, convém a saber: Olivaes, Vinhas e Moreiras, segundo a qualidade da terra. E assi fará enxertar todos os Azambugeiros, e tomar conta aos Officiaes das Cameras, das terras, em que entrar per correição, se fizeram semear e criar Pinhaes nos baldios dos ditos lugares, e criar as arvores, como no Título 66: Dos Vereadores he conteudo. E procederá contra os que assi o não cumprirem, segundo for a negligencia, em que incorrerem.

Que não carreguem os Concelhos.` },
        { id: 'of1-tlviii-47', number: '47', text: `E os Corregedores dos Mestrados e de quaesquer outros senhores de terras e Fidalgos não constrangerão os Concelhos de suas Comarcas, que dêm camas de graça aos Procuradores e Scrivães, que com elles andarem, nem que lhes levem mantimentos de um lugar a outro, nem lhos tomem por menos do que valerem commumente na terra, nem consintam que lhes seja tomado palha, nem lenha contra suas vontades. E os que cada huma das ditas cousas houverem mister, comprem-nas á vontade dos que as venderem segundo o stado da terra. Porém as pousadas mandamos que sejam dadas de graça aos sobreditos Officiaes, convém a saber, se forem casados, huma pousada a cada hum, e se forem solteiros, a dous uma pousada. E quando fôr necessario mandarem trazer mantimentos de fóra, não os mandarão vir senão pelos Officiaes do lugar, e serão súmente pão, vinho e carnes, que se vendam a peso e a talho, e outras algumas não.` },
        { id: 'of1-tlviii-48', number: '48', text: `Outrosi não constrangerão pessoas algumas, que lhes dêm bestas de albardas para suas carregas, nem dos Officiaes, que com elles andarem, nem para outras pessoas, salvo as que costumam ser alugadas, as quaes pagarão segundo o costume da terra.` },
        { id: 'of1-tlviii-49', number: '49', text: `Os Corregedores e Ouvidores devem trazer taes homens, que não façam dano na terra, e não sendo taes, os deitarão de sua companhia, e lhes darão o castigo, que merecerem. E não terão por Caminheiros homens seus, nem trarão elles, nem os Meirinhos e Alcaides escravo seu, nem alheio por homem de Justiça. E o que fizer o contrario, será suspenso do Officio por seis mezes, e pagará vinte cruzados, ametade para quem o accusar, e a outra para os Captivos.

Diligencias.` },
        { id: 'of1-tlviii-50', number: '50', text: `E quando per nossas Provisões lhes mandarmos fazer algumas diligencias e tomar informações a requerimento das partes, não lhes levarão dinheiro por lhas fazer nos lugares de sua correição, e as farão com brevidade, não perguntando em cada huma mais que tres testemunhas que tenham razão de saber o que lhes perguntarem, e não serão as que as partes lhes apresentarem. E nos enviarão as informações com os proprios autos, para as mandarmos ver, e dar despacho às partes. O que outrosi cumprirão os Provedores, Ouvidores e quaesquer Julgadores nos lugares de sua jurisdição.` },
        { id: 'of1-tlviii-51', number: '51', text: `E o Corregedor não porá em seu lugar Ouvidor sem muita necessidade. E havendo-a o poderá pôr per spaço de um mez sómente em cada huma anno, salvo quando for occupado em cousa de nosso serviço fóra da correição, porque então o porá em quanto a occupação durar. E se além do dito mez tiver tal necessidade que per si não possa servir, far-nol-o-ha saber, para pormos quem por elle sirva, em quanto durar a tal necessidade. E em nenhum caso porá por Ouvidor Procurador algum, postoqne perante elle não procure, nem Official algum dante elle. E stando em lugar, onde houver Juiz de fóra, porá o dito Juiz, e no tal tempo servirá de Juiz o Véreador mais velho. E não stando em lugar, onde houver Juiz de fóra, porá outra pessoa, que para isso lhe pareça sufficiente. E emquanto o dito Ouvidor tiver o tal Cargo, não tomará o Corregedor conhecimento de feito, nem cousa, que à correição pertença, assi stando hi, como sendo fóra, como indo, ou tornando. E fazendo o contrário de qualquer das cousas conteúdas neste paragrapho, pagará vinte cruzados, ametade para a arca da piedade, e a outra para quem o accusar e será suspenso do Officio alé nossa mercê.` },
        { id: 'of1-tlviii-52', number: '52', text: `Outrosi saberá si os privilegiados apousentados por idade, doença, ou aleijão o são sem malicia e sem engano. E se achar que não são apousentados como devem, proveja nisso, e não lhes consinta usar do tal privilegio que maliciosamente houveram.` },
        { id: 'of1-tlviii-53', number: '53', text: `E para o Corregedor fazer cumprir estas cousas, que a seu Officio pertencerem, e para outrosi saber se os Juizes e outros Officiaes da terra cumprem e guardam o que lhes he mandado, usará de seu Officio e andará per cada huma lugar de sua correição huma vez ao menos no anno; e nelles fará correição, postoqne sejam de Senhores de terras, por quanto os seus Ouvidores não podem usar nas ditas terras de correição, salvo tendo-o per special privilegio, como se dirá no Livro segundo Titulo 45 : Em que maneira os Senhores de terras, paragrapho 8 : E porque Correição. E não stará nos lugares grandes mais de trinta dias e nos pequenos até vinte dias, salvo se para isso houver nosso special mandado, ou se hi acontecer tal caso, que por bem de justiça seja necessário star mais tempo.` },
        { id: 'of1-tlviii-54', number: '54', text: `Fará screver a um Tabelliã.o, ou Scrivão, que com elle andar, todas as sentenças, que der em feitos civeis e crimes e instrumentos de aggravo, e as mais cousas que pertencerem, assi a bem de justiça, como entre partes, ou da governança da terra, para nos dar recado do que fez, ou áquelles, a que Nós mandarmos. O qual Tabelliã.o, ou Scrivão outrosi screva, quando o Corregedor entrar em cada lugar, e quantos dias ahi stiver, e quantos feitos desembargar, declarando o dia, mez e anno, em que entrou, e em que despachou os ditos feitos, e quem eram as partes, e sobre que cousa, e por qual das partes se deo a sentença, e se appellou a parte, ou o Corregedor, ou coube em sua alcada, ou se a parte stieve pela sentença, se fôr caso cível, e em que dia se tirou appellação, ou sentença, e passou pela Chancellaria : os quaes assentos darão em rol ao Chanceller da correição, e cobrarão delle conhecimento. E o dito Chanceller enviará os roes dos assentos à Corte per hum Caminheiro, e serão entregues ao Scrivão da nossa Camera da repartição dessa Comarca, para nos dello dar conta, do qual Scrivão o Caminheiro cobrará conhecimento. E bem assi assentará o Chanceller em seu rol com as ditas declarações o lugar, a que o Corregedor cada anno for per correição, ou fazer alguma diligencia per nosso mandado, ou de cada huma das Relações, ou per bem de justiça. E não sendo o Chanceller presente com o Corregedor, o encarregará a outro Scrivão, que com elle for, que assi o cumprirá. E o Scrivão, que o assi não fizer, incorrerá em perdimento do Officio. E a mesma pena terá o dito Chanceller se não cumprir o acima dito.` },
        { id: 'of1-tlviii-55', number: '55', text: `E não sairá dos lugares de sua correição, nem virá à Corte sem nossa li- cença, postoque tenha acabado seu tempo, salvo quando per cada huma das Relações, a que pertencer lhe for mandado fazer algumas diligencias a algumas outras Comarcas, ou jurisdições, ou pelos Védores de nossa Fazenda, porque então cumprirá o que lhe for mandado, sem mais licença nossa. E quando assi for fazer as ditas diligencies, ou outras, que cumpra a bem de justiça, ou de nossa Fazenda, não levará comsigo todos os Officiaes da correição, mas sómente um Scrivão, ou dous, e o Meirinho com ametade dos homens, que lhe são ordenados, e deixará o seu Ouvidor com outros Scrivães, e encarregará huma pessoa de confiança, que sirva de Meirinho com ametade dos ditos homens, nem levará comsigo alguma das partes, que com elle andarem. E sobrevindo algum caso, que cumpre a nosso serviço havermol-o de saber per elle, e que não deva ser notificado a outrem, então poderá vir, e não de outra maneira, sob pena de lhe ser tirado o mantimento, e de lho estranharmos, como nos parecer.` },
        { id: 'of1-tlviii-56', number: '56', text: `E os Corregedores e Ouvidores dos Mestrados terão alcada até oito mil réis nos bens de raiz, e dez mil réis nos moveis, sem appellação, nem aggravo. E nas penas, que puzerem, terão alcada até quantia de dous mil réis sómente, as quaes darão a execução sem appellação, nem aggravo.` },
        { id: 'of1-tlviii-57', number: '57', text: `E mandamos que os Corregedores cumpram e guardem todo o conteudo em este titulo, e em todos os capítulos delle: e não o cumprindo, nem guardando, haverão a pena, que nos bem parecer, segundo a qualidade dos casos, salvo nos capítulos, em que logo expressamente lhes he posta certa pena porque nesses será nelles executada.` },
      ],
    },
    {
      id: 'titulo-lix',
      title: `LIX. Dos Ouvidores, que per El-Rei são postos em alguns lugares`,
      type: 'articles',
      articles: [
        { id: 'of1-tlix-preambulo', number: 'Preâmbulo', text: `Quando pozermos por Ouvidor de alguma terra algum Juiz de fóra, posto per Nós em alguma Cidade, ou Villa, quando stiver no lugar de sua Ouvidoria, conhecerá de todo o que conheceria o Corregedor da Comarca, e usará de todo o que o Corregedor per seu Regimento hi póde usar, e terá a alcada, que tem no lugar de seu Julgado, e não aggravarão delle para o Corregedor, senão para onde poderiam aggravar do Corregedor; salvo quando elle conhecer per aução nova entre partes, nos casos, em que per seu Regimento póde, porque então poderiam delle aggravar, não cabendo em sua alcada, ou para Corregedor, ou para onde poderiam aggravar dante o Corregedor. E não stando o dito Ouvidor no lugar da Ouvidoria, as partes, que quizerem aggravar dante os Juizes do dito lugar, poderão aggravar para elle, ou para o Corregedor, qual as partes quiserem; e stando no dito lugar, não poderão aggravar senão para elle. E quando o Corregedor stiver no mesmo lugar, o Ouvidor não usará do dito Carrego em cousa alguma.` },
      ],
    },
    {
      id: 'titulo-lx',
      title: `LX. Como os Corregedores das Comarcas, Ouvidores dos Mestrados, e de Senhores de terras, e Juizes de fóra darão residencia`,
      type: 'articles',
      articles: [
        { id: 'of1-tlx-preambulo', number: 'Preâmbulo', text: `Ordenamos, que todo o Corregedor de Comarca, Ouvidor de algum Mestrado, ou de Senhor de terras e jurisdição, e Juizes de fóra, antes hum mez, ou dous, que acabem os tres annos de sua Correição, Ouvidoria, ou Judicatura, nos screva, como os tres annos de sua Correição, Ouvidoria Dar sua residencia, i. e., dar conta de sua vida e acções.

Tirar residencia, i. e., informar-se do procedimento de outrem.

ou Judicatura se acabam, para mandarmos hum Desembargador, ou outra pessoa, que nos bem parecer, à dita Comarca, Correição, ou lugar, tomar-lhe residencia. E as Cartas enviarão per Caminheiros, e serão entregues ao Scrivão de nossa Camera, a que pertencer, do qual levarão certidão, per elle assinada, de como lhas entregaram, e em que dia. E o Corregedor, Ouvidor, ou Juiz, que o assi não screver, seja privado do Officio, e nunca mais haja Officio de julgar.` },
        { id: 'of1-tlx-1', number: '1', text: `E o Desembargador, ou pessoa outra, que per nosso mandado for tomar a dita residencia, irá ao lugar cabeça da Correição, ou Ouvidoria, e mandará seus Alvarás a cinco, ou seis lugares da Comarca, para nelles se saber, e vir à noticia dos outros lugares della. Nos quaes Alvarás notificará e mandará pregoar, que toda a pessoa, que quizer demandar o dito Corregedor, ou Ouvidor, o venha perante elle demandar, por qualquer caso que seja. E stará o Desembargador hum mez no tal lugar, e hi ouvirá todos os que do Corregedor, ou Ouvidor se queixarem, ou aggravarem, tirando sobre isso as testemunhas, que lhe forem appresentadas; e proverá as partes, quanto a seus interesses, ou cousas, que lhes foram tomadas, ou levadas, até quantia de oito mil réis nos bens de raiz, e dez mil réis nos bens moveis, finalmente dando à execução suas sentenças, sem appellação nem aggravo. E sendo as demandas de maiores quantias, ou de tal qualidade, que mereça pena corporal, processará os feitos até os fazer conclusos, se poder no dito mez. E assi conclusos, e os que o não forem, passado o mez, trará com os autos da residencia à Mesa dos Desembargadores do Paço, para os mandarmos despachar finalmente per hum dos Corregedores da Corte do Crime, com os Desembargadores, que para isso lhe ordenarmos. E assinará tempo ao Corregedor, ou Ouvidor e às partes, a que appareçam na Corte; e não vindo, se procederá á revelia do que não vier, como for justiça.` },
        { id: 'of1-tlx-2', number: '2', text: `E em quanto o Desembargador tomar a residencia, o Corregedor ou Ouvidor será suspenso do Officio, e se sairá do lugar onde lha tomarem, per distancia de seis legoas ou mais, parecendo assi necessario ao Desembargador. E lhe nomeará lugar certo, onde sté, emquanto delle se tirar devassa, ou mais tempo, se assi parecer ao dito Desembargador, o qual usará do Officio de Corregedor, ou Ouvidor, não sendo provido de Corregedor, ou Ouvidor novo. E emquanto assi servir, despachará os feitos, que o Corregedor houvera de despachar. E nos que não couberem na alçada ordenada ao Corregedor, dará appellação e aggravo para a Relação, a que pertencer. E cabendo na dita alçada, os determinará sem appellação, nem aggravo. E a pessoa, que mandarmos tomar residencia a algum Juiz de fóra, entregará a vara do dito Juiz ao Vereador mais antigo. E sendo o Corregedor da Comarca o que assi lhe tomar residencia, ouvirá as partes contra o dito Juiz. E nos feitos, que couberem na alçada delle Corregedor, dará determinação sem appellação, nem aggravo. E nos que nella não couberem, dará appellação e aggravo para a Relação, a que pertencer, assinando termo às partes e ao Juiz, em que a vão seguir. E no mais se guardará o que temos dito ácerca das residencias dos Corregedores.` },
        { id: 'of1-tlx-3', number: '3', text: `E se o Corregedor, ou Ouvidor, que houver de fazer a residencia, fugir, ou a não vier fazer, havemos por bem, que todos os crimes e excessos, e causas, por que for demandado, ou accusado per razão de seu Officio perante o Desembargador no dito lugar, sejam havidos por provados e confessados, como se fossem perfeitamente provados per legitimas provas, postoque a elles não seja dado prova alguma.` },
        { id: 'of1-tlx-4', number: '4', text: `E como o Corregedor for saído do lugar e os pregões lançados, o Desembargador perguntará per juramento os Officiaes da Correição, e os Juizes e Officiaes, que servirão no seu tempo, e Tabelliães, e alguns homens mais principaes, que tenham razão de o saber, se tem o Corregedor cumprido o que lhe he mandado em seu Regimento; e assi pelos capitulos seguintes, declarando-lhes, que o Corregedor não ha mais de tornar à dita correição: e o que disserem, assi de bem como de mal, mandará screver.` },
        { id: 'of1-tlx-5', number: '5', text: `E saberá se em cada anno fez correição, per todos os lugares de sua Comarca, e se em alguns delles deixou de entrar e fazer correição per rogo, ou temor dos Senhores delles, e se steve mais tempo nos lugares do que per seu Regimento lhe he mandado. E para isso verá o caderno, que o Scrivão da correição he obrigado fazer de todo o que o Corregedor fez em cada lugar. E per elle e pelos Scrivães da correição se informará, se fez correição sobre os Officiaes da Justiça dos ditos lugares, specialmente se vio as Cartas e Regimentos de seus Officios, e os livros das notas e das querelas, e se proveo as devassas, e cumprio ácerca disso seu Regimento.` },
        { id: 'of1-tlx-6', number: '6', text: `Item, se fez que a nossa jurisdição fosse bem guardada, ou se per sua vontade deixava aos Ecclesiasticos usar della em nosso prejuizo, ou aos Senhores de terras, ou a seus Ouvidores usar de mais jurisdição da que tinham per suas doações, ou dar alguns Officios, que per bem dellas não podiam dar.` },
        { id: 'of1-tlx-7', number: '7', text: `Se tomou aos Ecclesiasticos, ou Senhores de terras, ou aos Concelhos alguma cousa das jurisdições, que lhes pertencem, conhecendo de cousas, de que não devêra conhecer.` },
        { id: 'of1-tlx-8', number: '8', text: `Se vio os Foraes de cada lugar, e trabalhou saber se alguem foi contra elles, arrecadando mais direitos do que podia, e o que ácerca disso fez.` },
        { id: 'of1-tlx-9', number: '9', text: `Se recebia peitas, ou dadivas de alguns Grandes, ou Fidalgos, por lhes ser favoravel em seus feitos, ou dos seus, ou de quaesquer pessoas de sua Comarca, que perante elle requeressem despachos, ou já os tivessem requeridos, e que taes eram: Ou se houve emprestimos, ou fez compras, ou trocas de algumas cousas com algumas pessoas, que perante elle litigassem, ou requeressem despacho, em quanto perante elle o litigio, ou requerimento durou; ou de outras pessoas de O Direito antigo era mais severo com o Juiz; exigia mais decoro no seu comportamento. O que se póde esperar de um Magistrado que emprega o seu tempo em descontos?

que seja defeso per nossas Ordenações: Ou se tomava mantimentos, ou cousas outras sem as pagar, ou por menos do que valiam: Ou se fazia servir alguns homens com seus corpos, carros e bestas, ou outras serventias, não lhes pagando o que direitamente lhes era ordenado, ou fazia a algumas pessoas sem razões algumas.` },
        { id: 'of1-tlx-10', number: '10', text: `E se tinha cuidado de saber, se em sua correição havia malfeitores, e sabendo-o, se os prendia, ou fazia prender, para se fazer delles cumprimento de justiça, ou se delles deu favor de andarem perante elle, ou em sua correição, ou lhes deu lugar, que a seu salvo se fossem.` },
        { id: 'of1-tlx-11', number: '11', text: `Se deixou de mandar pagar algumas malfeitorias, ou tomadias, que em sua Comarca fossem feitas per Fidalgos, ou Abbades e pessoas poderosas, ou roubos, que criados dos sobreditos fizessem nella, de maneira que os queixosos não ficassem satisfeitos.` },
        { id: 'of1-tlx-12', number: '12', text: `E se nos lugares da Comarca, per onde andava, fazia concertar as pontes, fontes, caminhos, e prover as prisões das cadeas.` },
        { id: 'of1-tlx-13', number: '13', text: `E se fazia aos Scrivães dante elle, e aos Tabelliães e Scrivães de sua Comarca, guardar e cumprir os Regimentos, que juraram em nossa Chancellaria, e despachar as scripturas ás partes, e não lhes levar por ellas mais, do que lhes he taxado. E se consentia a alguns, que com elle andassem, fazer maleficios em dano da terra.` },
        { id: 'of1-tlx-14', number: '14', text: `Se achou que em sua Comarca havia bandos entre Fidalgos, ou Concelhos huns contra os outros, e se trabalhou polos tirar e paziguar, de maneira que todos fossem em boa concordia.` },
        { id: 'of1-tlx-15', number: '15', text: `Outrosi se achou algumas villas, ou lugares despovoados, se trabalhou como se tornassem a povoar. E se fez aproveitar as herdades e vinhas, e plantar arvores.` },
        { id: 'of1-tlx-16', number: '16', text: `E perguntará, se levava dinheiro ás partes por fazer as diligencias que per nossas Provisões lhe mandámos fazer, e informações, que lhe mandámos tomar a requerimento das partes nos lugares de suas correições. E se foi remisso em as fazer, como he conteúdo em seu Regimento.` },
        { id: 'of1-tlx-17', number: '17', text: `E se fazia audiencias às partes aos tempos ordenados, e se despachava os feitos com brevidade, guardando às partes seu direito.` },
        { id: 'of1-tlx-18', number: '18', text: `E perguntará às testemunhas, se sabem algumas cousas além das aqui conteúdas, e das que disserem, serão perguntados, como o sabem, e per quem, e quaes eram as mais pessoas culpadas nisso com o Corregedor, ou que disso saibam; e assi serão declaradas. E referindo-se as testemunhas à outras pessoas, sejam logo perguntadas de maneira que a verdade seja sabida.` },
        { id: 'of1-tlx-19', number: '19', text: `Mandará outrosi aos Scrivães da correição, que lhe mostrem todos os feitos crimes despachados pelo Corregedor, em que não appellou, e verá se deixou de appellar em alguns, que não cabiam em sua alçada, assi elle, como as pessoas que serviram em sua absencia.` },
        { id: 'of1-tlx-20', number: '20', text: `E achando que o Corregedor foi negligente em alguma cousa de seu Officio, ou que teve culpa em levar o que não podia, o perguntará por isso, mandando-o chamar, parecendo-lhe necessário, para que diga a razão, que teve. E se for tal que se haja de ver per livros e papeis, os verá logo, e fará declaração nos autos da residencia, do que nisso achar, para se escusar mandar depois pelos livros e papeis para seu despacho.` },
        { id: 'of1-tlx-21', number: '21', text: `E pela mesma maneira saberá como os Scrivães, Meirinho e Officiaes dante o Corregedor tem servido seus Officios, tirando sobre elles inquirição: e ouvira as pessoas, que os quizerem demandar, e fará o que for justiça.` },
        { id: 'of1-tlx-22', number: '22', text: `E todo o que se achar, fará screuer e fazer declaração nos autos da residencia, pelo Scrivão della, de cada cousa, em cada capítulo apartado.` },
      ],
    },
  ],
};
